:root{color-scheme:light;--ink:#242c48;--muted:#59637a;--paper:#f3f5fa;--line:#cbd1df;--accent:#50478b;--wash:#e9e7f4;--white:#fff}
*{box-sizing:border-box}
body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 "Segoe UI", "Helvetica Neue", Arial,sans-serif}
a{color:var(--accent);text-underline-offset:4px}
header,footer{max-width:1240px;margin:auto;padding:28px 40px;display:flex;justify-content:space-between;gap:20px;align-items:center}
.brand{font-size:20px;font-weight:700;letter-spacing:-.6px;text-decoration:none;color:var(--ink)}
nav{font-size:14px}
main{max-width:1240px;margin:40px auto 80px;padding:0 40px;display:grid;grid-template-columns:minmax(240px, .8fr) minmax(0,1.35fr);gap:72px;align-items:start}
.intro{padding:30px 0}
.product-name{font-weight:650;color:var(--accent);margin:0 0 22px}
h1{font-size:clamp(32px,3.3vw,46px);line-height:1.12;letter-spacing:-1.8px;font-weight:550;margin:0 0 26px}
h2{font-size:26px;line-height:1.3;letter-spacing:-.6px;font-weight:550}
h3{font-size:17px;margin:0}
p{margin:0 0 18px}
.lede{font-size:20px;line-height:1.5}
