.text-link{display:inline-block;font-size:14px;margin-top:14px}
.conversation-space{background:var(--white);padding:32px 36px;border-radius:8px 8px 24px 8px;border-top:4px solid var(--accent);min-width:0;box-shadow:0 8px 30px #242c4808}
