@media(max-width:800px){header,footer{padding:22px 24px}
main,body.in-session main{grid-template-columns:1fr;gap:28px;margin-top:10px;padding:0 24px;max-width:640px}
.intro{padding:10px 0 0}
.intro h1{font-size:36px;margin-bottom:18px}
.intro .lede{font-size:18px;margin-bottom:14px}
.intro>p:not(.product-name):not(.lede),.intro>.text-link{display:none}
.product-name{margin-bottom:12px}
.conversation-space{padding:24px}
.opening h2{font-size:28px}
.opening{padding-bottom:22px}
body.in-session .intro{display:none}
body.in-session main{margin-top:12px}
.bubble.participant{margin-left:20px}
header{align-items:baseline}
.brand{font-size:18px}
nav{font-size:13px}
}
@media(max-width:380px){header,footer{padding:20px 16px}
main,body.in-session main{padding:0 16px}
.conversation-space{padding:20px}
.actions{gap:8px}
button{padding:10px 14px}
}

.fixture-notice{margin:0 auto;padding:8px 40px;max-width:1240px;font-size:12px;color:var(--muted)}

/* Second visual pass: let the question lead on narrow screens. */
@media(max-width:800px){.intro h1{font-size:29px;letter-spacing:-1px;margin-bottom:12px}
.intro h1 br{display:none}
.intro .lede{font-size:16px;line-height:1.5}
.product-name{font-size:14px;margin-bottom:8px}
.opening h2{font-size:25px;line-height:1.32;margin:10px 0 16px}
#runtime{margin-bottom:16px}
.opening>.speaker{display:none}
.session-top{gap:10px}
.session-top p{flex:1;min-width:150px}
.session-top button{font-size:13px;padding:8px 12px}
.bubble{padding:20px 0}
.fixture-notice{padding:4px 24px}
}


/* The opening question carries the identity; surrounding controls stay quiet. */
h1,h2{font-weight:400}

.intro h1{font-size:38px;letter-spacing:-1.4px}

.opening h2{font-size:34px;letter-spacing:-.8px;margin-top:0}

.conversation-space{box-shadow:none;border-radius:3px 3px 16px 3px;border-top-width:2px}

#admission>summary,button:not(.secondary){background:var(--ink);border-color:var(--ink)}

#key-panel{padding:10px 0;border-bottom:1px solid var(--line)}

#key-panel summary{font-weight:400}

#key-panel:not([open]){margin-bottom:8px}

.session-top{margin-bottom:12px}

#turn .small{max-width:65ch}

textarea::placeholder{color:var(--muted);opacity:1}

@media(max-width:800px){.intro h1{font-size:29px}
.opening h2{font-size:27px}
.session-top{align-items:center}
.session-top p{font-size:13px}
.session-top button{border-color:var(--line)}
#key-panel{padding:8px 0}
.bubble{padding:18px 0}
