1	'use strict';
2	const $ = id => document.getElementById(id);
3	let token = '', session = null, busy = false;
4	async function api(path, method = 'GET', data, auth = token) {
5	  const response = await fetch(path, {method, headers: {'Content-Type': 'application/json', 'Authorization': `Bearer ${auth}`}, ...(data === undefined ? {} : {body: JSON.stringify(data)})});
6	  const value = await response.json();
7	  if (!response.ok) throw new Error(value.error || 'Request failed. Reload before retrying.');
8	  return value;
9	}
10	async function run(work, status = 'Updating conversation…', focusAfter = null) {
11	  if (busy) return;
12	  busy = true; $('error').textContent = '';
13	  const active = document.activeElement;
14	  const oldLabel = !session && active?.tagName === 'BUTTON' ? active.textContent : null;
15	  if (oldLabel) active.textContent = status;
16	  $('activity').textContent = status; $('activity').hidden = false;
17	  $('message').readOnly = true;
18	  document.querySelectorAll('button').forEach(b => { b.disabled = true; });
19	  let succeeded = false;
20	  try { await work(); succeeded = true; }
21	  catch (error) {
22	    $('error').textContent = `${error.message} ${session ? 'Your draft is still here. Reload the session before retrying if a reply may have been sent.' : 'Check your code or key, then try again.'}`;
23	  }
24	  finally {
25	    busy = false; $('activity').hidden = true; $('message').readOnly = false;
26	    if (oldLabel) active.textContent = oldLabel;
27	    document.querySelectorAll('button').forEach(b => { b.disabled = false; });
28	    if (session) render();
29	    if (!succeeded) $('error').focus();
30	    else if (focusAfter) {
31	      const target = document.querySelector(focusAfter);
32	      if (target) {
33	        if (!target.matches('button, input, textarea, summary, a[href]')) target.setAttribute('tabindex', '-1');
34	        target.focus({preventScroll:true}); target.scrollIntoView({block:'nearest'});
35	      }
36	    }
37	  }
38	}
39	function bubble(who, text) {
40	  const div = document.createElement('div'); div.className = 'bubble' + (who === 'You' ? ' participant' : '');
41	  const label = document.createElement('span'); label.className = 'speaker'; label.textContent = who;
42	  const p = document.createElement('p'); p.textContent = text; div.append(label, p); $('turns').append(div);
43	}
44	function render() {
45	  document.body.classList.add('in-session');
46	  $('onboarding').hidden = true; $('conversation').hidden = false;
47	  const legacy = session.schema_version !== 2 || session.consent_version !== '2026-10-05-native-providers';
48	  const ended = legacy || session.phase === 'complete';
49	  $('phase').textContent = legacy ? 'Earlier session · read-only' : `${session.version} of ${session.max_exchanges} exchanges · ${ended ? 'ended' : 'you can pause or finish sooner'}`;
50	  $('session-key').value = token;
51	  $('turns').replaceChildren();
52	  if (session.intake) bubble('Earlier context', JSON.stringify(session.intake, null, 2));
53	  else bubble('Help · opening question', session.opening);
54	  for (const turn of session.turns) { bubble('You', turn.input); bubble('Help', turn.reply); }
55	  if (legacy && session.experiment) bubble('Earlier proposal', JSON.stringify(session.experiment, null, 2));
56	  $('legacy').hidden = !legacy;
57	  $('turn').hidden = ended;
58	  $('completed').hidden = !ended || legacy;
59	  $('send').textContent = session.version === session.max_exchanges - 1 ? 'Send final message' : 'Send';
60	  $('expiry').textContent = `Access expires ${new Date(session.expires_at * 1000).toLocaleString()}.`;
61	}
62	$('admission-form').addEventListener('submit', event => {
63	  event.preventDefault(); run(async () => {
64	    const value = await api('/api/sessions', 'POST', {consent: $('consent').checked}, $('pilot').value);
65	    token = value.token; session = value.session; $('pilot').value = '';
66	  }, 'Opening conversation…', '#turns .bubble:last-child');
67	});
68	$('resume').addEventListener('submit', event => {
69	  event.preventDefault(); run(async () => {
70	    const candidate = $('resume-key').value.trim();
71	    const value = await api('/api/session', 'GET', undefined, candidate);
72	    token = candidate; session = value.session; $('resume-key').value = '';
73	  }, 'Resuming…', '#turns .bubble:last-child');
74	});
75	$('turn').addEventListener('submit', event => {
76	  event.preventDefault(); const action = event.submitter?.value || 'message';
77	  run(async () => { const value = await api('/api/turn', 'POST', {version: session.version, action, text: $('message').value}); session = value.session; $('message').value = ''; }, 'Waiting for a reply…', '#turns .bubble:last-child');
78	});
79	$('reload').addEventListener('click', () => run(async () => { session = (await api('/api/session')).session; }));
80	$('reveal').addEventListener('click', () => { $('session-key').type = $('session-key').type === 'password' ? 'text' : 'password'; });
