:root{color-scheme:light;
--ink:#1c2420;--muted:#5c6a62;--paper:#eef1ea;--line:#c9d2c4;
--accent:#3f6b52;--accent-ink:#2c4d3c;--focus:#8a5a2b;
--wash:#dde6d7;--agent-ink:#32465a;--agent-wash:#e9edf1;--white:#fff;
--err:#8a2f3f;--err-bg:#fbeaec;
--sans:-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
--serif:ui-serif,"Iowan Old Style","Palatino Linotype","Book Antiqua",Georgia,serif;
--mono:ui-monospace,"SFMono-Regular",Menlo,Consolas,"Liberation Mono",monospace;
}
*{box-sizing:border-box}
body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 var(--sans)}
a{color:var(--accent-ink);text-underline-offset:4px}
header,footer{max-width:1240px;margin:auto;padding:28px 40px;display:flex;justify-content:space-between;gap:20px;align-items:center}
.brand{font-family:var(--serif);font-size:21px;font-weight:600;text-decoration:none;color:var(--ink)}
nav{font-size:14px;display:flex;gap:18px}
main{max-width:1240px;margin:40px auto 80px;padding:0 40px;display:grid;grid-template-columns:minmax(240px, .8fr) minmax(0,1.35fr);gap:72px;align-items:start}
.intro{padding:30px 0}
.product-name{font-weight:650;color:var(--accent-ink);margin:0 0 20px;font-size:14px}
h1,h2{font-family:var(--serif);font-weight:500;margin:0 0 24px}
h1{font-size:clamp(30px,3vw,42px);line-height:1.2;max-width:14ch}
h2{font-size:26px;line-height:1.3}
h3{font-size:17px;margin:0;font-family:var(--sans);font-weight:650}
p{margin:0 0 18px;max-width:60ch}
.lede{font-size:19px;line-height:1.5}
.small{font-size:14px;color:var(--muted)}
.text-link{display:inline-block;font-size:14px;margin-top:14px}
.conversation-space{background:var(--white);padding:32px 36px;border:1px solid var(--line);border-top:3px solid var(--accent);min-width:0}
#runtime{font-size:13px;color:var(--muted);margin-bottom:24px}
.opening{padding-bottom:26px}
.opening h2{font-size:30px;line-height:1.28;margin:12px 0 20px;max-width:22ch}
.opening p{font-size:14px;color:var(--muted);margin:0;font-family:var(--sans)}
.speaker{font-size:13px;font-weight:650;color:var(--accent-ink);font-family:var(--sans)}
.agent-voice .speaker{color:var(--agent-ink)}
.bubble-tag{font-size:12px;color:var(--muted);font-family:var(--sans);margin:0 0 6px}
details{border-top:1px solid var(--line);padding:18px 0}
summary{cursor:pointer;font-weight:600;color:var(--accent-ink);min-height:28px}
details[open]>summary{margin-bottom:18px}
#admission{border:0;padding:0 0 22px}
#admission>summary{background:var(--ink);border-color:var(--ink);color:white;padding:13px 18px;list-style:none;text-align:center}
#admission>summary::-webkit-details-marker{display:none}
#admission[open]>summary{background:var(--wash);color:var(--accent-ink)}
.sample{margin-top:0}
.sample>div{padding:16px 0}
.sample p{margin:8px 0}
.privacy{font-size:14px;background:var(--paper);padding:20px;margin:24px 0}
.privacy p{margin:12px 0}
label{display:block;font-weight:600;margin:18px 0 8px;font-family:var(--sans)}
input,textarea,button{font:inherit}
input:not([type=checkbox]),textarea{width:100%;border:1px solid #8993ab;background:white;border-radius:3px;padding:12px;color:var(--ink);font-family:var(--sans)}
input:not([type=checkbox]){margin-top:6px}
textarea{min-height:132px;resize:vertical;line-height:1.6;font-family:var(--mono);font-size:15px}
textarea::placeholder{color:var(--muted);opacity:1;font-family:var(--sans)}
.check{display:flex;gap:12px;align-items:flex-start;font-size:14px;font-weight:400;margin-bottom:20px;font-family:var(--sans)}
.check input{min-width:20px;height:20px;margin:2px 0;accent-color:var(--accent)}
button{border:1px solid var(--ink);border-radius:3px;background:var(--ink);color:white;padding:10px 18px;min-height:46px;cursor:pointer;font-weight:600;font-family:var(--sans)}
button:disabled{opacity:.6;cursor:wait}
.secondary{background:transparent;color:var(--accent-ink);border-color:var(--line)}
.actions,.session-top{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.actions{margin-top:14px}
.session-top{justify-content:space-between;margin-bottom:12px}
#phase{margin:0;font-family:var(--sans);font-size:14px;display:flex;align-items:baseline;gap:12px;flex-wrap:wrap}
#phase .count{font-family:var(--mono);font-weight:600;color:var(--ink)}
#phase .status{color:var(--muted);padding-left:12px;border-left:1px solid var(--line)}
#key-panel{font-size:14px;padding:10px 0;border-bottom:1px solid var(--line)}
#key-panel summary{font-weight:400}
#key-panel:not([open]){margin-bottom:8px}
#key-panel button{margin-top:12px}
.bubble{padding:18px 0;white-space:pre-wrap;overflow-wrap:anywhere}
.bubble p{margin:8px 0 0;font-family:var(--serif);font-size:17px;line-height:1.55;max-width:62ch}
.bubble.agent-voice p{font-family:var(--mono);font-size:14.5px;line-height:1.65}
.bubble.participant{padding:16px 20px;margin:8px 0 8px 32px;background:var(--agent-wash)}
#turn{border-top:1px solid var(--line);padding-top:12px}
#turn .small{margin:16px 0;max-width:65ch}
#expiry{margin-top:26px}
#delete{font-size:14px}
#error{color:var(--err);background:var(--err-bg);padding:14px;margin:20px 0 0;border-left:3px solid var(--err);font-family:var(--sans)}
#error:empty{display:none}
#activity{margin:18px 0;color:var(--accent-ink);font-family:var(--sans)}
#completed{background:var(--wash);padding:24px;margin-top:24px}
#completed h2{margin-top:0}
footer{font-size:13px;border-top:1px solid var(--line)}
footer nav{gap:20px}
[hidden]{display:none!important}
:focus-visible{outline:3px solid var(--focus);outline-offset:4px}
body.in-session main{grid-template-columns: minmax(190px,.55fr) minmax(0,1.45fr);gap:64px}
body.in-session h1{font-size:30px}
body.in-session .intro .lede{font-size:17px}
body.in-session #runtime{display:none}
pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--wash);padding:18px;border-radius:3px;font-family:var(--mono)}
code{overflow-wrap:anywhere;font-family:var(--mono)}
body.api-page main{display:block;max-width:820px}
body.api-page h1{font-size:38px}
body.api-page h2{margin-top:42px;font-size:23px}
body.api-page p,body.api-page li{max-width:75ch}
body.api-page nav{display:flex;flex-wrap:wrap;gap:16px;margin:24px 0}

.fixture-notice{margin:0 auto;padding:8px 40px;max-width:1240px;font-size:12px;color:var(--muted)}

@media(max-width:800px){header,footer{padding:22px 24px}
main,body.in-session main{grid-template-columns:1fr;gap:28px;margin-top:10px;padding:0 24px;max-width:640px}
.intro{padding:10px 0 0}
.intro h1{font-size:28px;line-height:1.22;margin-bottom:16px;max-width:none}
.intro .lede{font-size:17px;margin-bottom:14px}
.intro>p:not(.product-name):not(.lede),.intro>.text-link{display:none}
.product-name{margin-bottom:10px}
.conversation-space{padding:22px}
.opening h2{font-size:25px;line-height:1.32;margin:10px 0 16px}
.opening{padding-bottom:22px}
.opening>.speaker{display:none}
body.in-session .intro{display:none}
body.in-session main{margin-top:12px}
.bubble{padding:14px 0}
.bubble.participant{margin-left:18px}
header{align-items:baseline}
.brand{font-size:18px}
nav{font-size:13px}
#runtime{margin-bottom:16px}
.session-top{gap:10px}
.session-top button{font-size:13px;padding:8px 12px}
#phase{font-size:13px}
#key-panel{padding:8px 0}
.fixture-notice{padding:4px 24px}
}
@media(max-width:380px){header,footer{padding:20px 16px}
main,body.in-session main{padding:0 16px}
.conversation-space{padding:18px}
.actions{gap:8px}
button{padding:10px 14px}
}
